# ==========================================================
# WazuhShareSync + share-sync.ps1 — Single-File Installer v2.0
# ==========================================================
# Drops both scripts to "$Source", then runs install-service.ps1.
#
# Usage (elevated PowerShell):
#   PowerShell -ExecutionPolicy Bypass -File install.ps1
#   PowerShell -ExecutionPolicy Bypass -File install.ps1 -Uninstall
# ==========================================================

param([switch]$Uninstall)

$ErrorActionPreference = "Stop"

$Source      = "C:\\Program Files (x86)\\ossec-agent\\shared"
$ScriptPath  = Join-Path $Source "share-sync.ps1"
$Installer   = Join-Path $Source "install-service.ps1"

function Write-Info  { Write-Host "INFO   $_" -Foreground Cyan }
function Write-Ok    { Write-Host "OK     $_" -Foreground Green }
function Write-Warn  { Write-Host "WARN   $_" -Foreground Yellow }
function Write-Fatal { Write-Host "FATAL  $_" -Foreground Red; exit 1 }

# ----- Pre-flight: elevated + Wazuh agent present -----
if ((([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) -eq $false) {
    Write-Fatal "Run as Administrator (elevated prompt)."
}
if (!(Test-Path "C:\\Program Files (x86)\\ossec-agent")) {
    Write-Fatal "Wazuh agent not installed at expected path."
}

# ----- Materialise scripts from embedded base64 -----
New-Item -ItemType Directory -Path $Source -Force | Out-Null

$SyncB64      = ""
$InstallerB64 = ""

[IO.File]::WriteAllBytes($ScriptPath, [Convert]::FromBase64String($SyncB64))
[IO.File]::WriteAllBytes($Installer,  [Convert]::FromBase64String($InstallerB64))

Write-Ok ("Wrote:   " + $ScriptPath + "   (" + ([IO.FileInfo]$ScriptPath).Length + " bytes)")
Write-Ok ("Wrote:   " + $Installer  + "     (" + ([IO.FileInfo]$Installer).Length + " bytes)")

# ----- Hand off to install-service.ps1 -----
& powershell.exe -NoProfile -ExecutionPolicy Bypass -File $Installer @PSBoundParameters

if ($LASTEXITCODE -ne 0) {
    Write-Fatal ("install-service.ps1 exited " + $LASTEXITCODE)
}
Write-Ok "Done."
